#!/usr/bin/env bash
#
# A wizard walks a human through setting up headless PDF translation (BabelDOC).
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

TOTAL_STAGES=0
_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-$HOME/wsl-workspace/zotero-cli/.env}"
WRITTEN_ENV=()
WRITTEN_SECRET=()
SKIPPED=()

_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  本向导将带你配置无头 PDF 双语排版翻译引擎（BabelDOC），\n' "$DIM"
  printf '  实现与 Zotero-CLI / OpenAlex 的无缝结合，保留论文公式与多栏排版。\n'
  printf '  随时可按 Ctrl-C 退出，已保存的配置会自动保留。%s\n' "$RESET"
  pause "准备好开始了吗？按 Enter 键继续..."
}

stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ 步骤 %s/%s · %s%s\n\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

say()  { printf '  %s\n' "$1"; }
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

open_url() {
  local url="$1"
  printf '  %s↗ 打开链接%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "无法自动打开浏览器，请手动访问: $url"; fi
  } >/dev/null 2>&1 || warn "无法自动打开浏览器，请手动访问: $url"
}

pause() {
  printf '  %s%s%s ' "$DIM" "${1:-按 Enter 键继续}" "$RESET"
  read -r _ || true
}

confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter 保留当前值: %s]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$current" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter 保留已保存密码/Key]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ 已写入%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ 已设置%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name")
}

set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ 已设置%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
}

finish() {
  _clear
  printf '\n%s%s  ✓ 无头翻译引擎配置完成！%s\n\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} )) && note "已保存配置项至 $ENV_FILE: ${WRITTEN_ENV[*]}"
  printf '\n'
  say "你现在可以在无头模式下翻译论文并自动挂载到 Zotero 库："
  say "命令示例："
  say "  babeldoc --files paper.pdf --openai-base-url \"\$TRANSLATE_BASE_URL\" \\"
  say "           --openai-model \"\$TRANSLATE_MODEL\" --openai-api-key \"\$TRANSLATE_API_KEY\""
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=4

banner "无头 PDF 双语翻译引擎配置向导 (BabelDOC)"

# ── Stage 1: 安装与环境检测 ──────────────────────────────────────────────
stage "检查并安装 BabelDOC CLI 引擎"
say "BabelDOC 是沉浸式翻译同源的开源 PDF 学术排版翻译引擎，支持公式保留与多栏排版。"

if command -v babeldoc >/dev/null 2>&1; then
  say "检测到 babeldoc 已安装在系统中。"
else
  step "正在使用 uv 安装 BabelDOC CLI 工具..."
  if /home/q2635/.local/bin/uv tool install --python 3.12 BabelDOC; then
    say "BabelDOC 安装成功！"
  else
    warn "uv tool 安装遇到问题，尝试使用 pip 安装..."
    pip install BabelDOC
  fi
fi
pause "按 Enter 键进入模型与 API 配置..."

# ── Stage 2: 选择翻译模型与 API 服务 ────────────────────────────────────
stage "选择翻译服务供应商"
say "BabelDOC 支持任意兼容 OpenAI 接口的模型（推荐 DeepSeek-V3，高性价比且学术术语极准）。"
say "服务类型选择："
say "  [1] DeepSeek 官方 API (https://api.deepseek.com/v1 - 推荐)"
say "  [2] OpenAI 官方 API (https://api.openai.com/v1)"
say "  [3] 自定义中转 / 代理接口 (如个人中转站、公司网关)"
say ""
ask CHOICE "请输入序号 [1/2/3，默认 1]:"
CHOICE="${CHOICE:-1}"

if [[ "$CHOICE" == "1" ]]; then
  DEFAULT_BASE="https://api.deepseek.com/v1"
  DEFAULT_MODEL="deepseek-chat"
  say "已选择 DeepSeek 官方 API。"
  if confirm "是否打开 DeepSeek 开放平台复制 API Key？"; then
    open_url "https://platform.deepseek.com/api_keys"
  fi
elif [[ "$CHOICE" == "2" ]]; then
  DEFAULT_BASE="https://api.openai.com/v1"
  DEFAULT_MODEL="gpt-4o-mini"
  say "已选择 OpenAI 官方 API。"
  if confirm "是否打开 OpenAI 控制台复制 API Key？"; then
    open_url "https://platform.openai.com/api-keys"
  fi
else
  DEFAULT_BASE=""
  DEFAULT_MODEL=""
  say "已选择自定义接口。"
fi

# ── Stage 3: 录入 API 凭证 ──────────────────────────────────────────────
stage "录入 API 连接参数与密钥"

ask TRANSLATE_BASE_URL "输入 API Base URL (如 $DEFAULT_BASE):"
TRANSLATE_BASE_URL="${TRANSLATE_BASE_URL:-$DEFAULT_BASE}"

ask TRANSLATE_MODEL "输入翻译模型名称 (如 $DEFAULT_MODEL):"
TRANSLATE_MODEL="${TRANSLATE_MODEL:-$DEFAULT_MODEL}"

step "输入你的 API Key（输入将被隐藏，保证安全）："
ask_secret TRANSLATE_API_KEY "API Key:"

# ── Stage 4: 写入持久化配置 ──────────────────────────────────────────────
stage "保存配置并写入环境"

write_env "TRANSLATE_BASE_URL" "$TRANSLATE_BASE_URL"
write_env "TRANSLATE_MODEL" "$TRANSLATE_MODEL"
write_env "TRANSLATE_API_KEY" "$TRANSLATE_API_KEY"

# 同时在 ~/.config/babeldoc/env 保存一份副本供全局调用
mkdir -p "$HOME/.config/babeldoc"
cat <<EOF > "$HOME/.config/babeldoc/env"
export TRANSLATE_BASE_URL="$TRANSLATE_BASE_URL"
export TRANSLATE_MODEL="$TRANSLATE_MODEL"
export TRANSLATE_API_KEY="$TRANSLATE_API_KEY"
EOF
chmod 600 "$HOME/.config/babeldoc/env"
say "✓ 已同步写入 ~/.config/babeldoc/env"

finish
